using Microsoft.EntityFrameworkCore;
class ProductContext : DbContext
{
    public DbSet<Product> Products => Set<Product>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Product>(entity =>
        {
            entity.ToContainer("Products");

            // EF Core 9 renamed the discriminator property from "Discriminator" to "$type".
            // Preserve the EF Core 8 property name so existing 500K documents remain readable
            // and raw SQL queries referencing c.Discriminator keep working.
            entity.HasDiscriminator<string>("Discriminator");

            // EF Core 9 changed the id format from "EntityName|<key>" to just "<key>".
            // Use IdProperty + HasValueGenerator to preserve the "Product|<key>" format
            // so existing documents are still addressable.
            entity.Property(p => p.Id)
                  .ToJsonProperty("id")
                  .HasValueGeneratorFactory<LegacyCosmosIdGeneratorFactory>();
        });
    }
}

class Product
{
    public string Id { get; set; } = default!;
    public string Sku { get; set; } = default!;
}

